import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"17、【隨】 震下兌上","description":"周易口訣義 - 17、【隨】 震下兌上","frontmatter":{"title":"17、【隨】 震下兌上","description":"周易口訣義 - 17、【隨】 震下兌上"},"headers":[],"relativePath":"classics/koujueyi/019.md","filePath":"classics/koujueyi/019.md"}'),r={name:"classics/koujueyi/019.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_17、【隨】-震下兌上" tabindex="-1">17、【隨】 震下兌上 <a class="header-anchor" href="#_17、【隨】-震下兌上" aria-label="Permalink to “17、【隨】 震下兌上”">​</a></h1><p>彖曰：「隨」，剛來而下柔，動而說，隨。大亨貞無咎，而天下隨時。隨時之義大矣哉！</p><p>象曰：澤中有雷，隨，君子以嚮晦入宴息。</p><p>初九：官有渝，貞吉。出門交有功。</p><p>象曰：「官有渝」，從正吉也。「出門交有功」，不失也。</p><p>六二：系小子，失丈夫。</p><p>象曰：「系小子」，弗兼與也。</p><p>六三：系丈夫，失小子，隨有求得，利居貞。</p><p>象曰：「系丈夫」，志舍下也。</p><p>九四：隨有獲，貞兇。有孚在道以明，何咎？</p><p>象曰：「隨有獲」，其義兇也。「有孚在道」，明功也。</p><p>九五：孚於嘉，吉。</p><p>象曰：「孚於嘉吉」，位正中也。</p><p>上六：拘繫之，乃從維之，王用亨於西山。</p><p>象曰：「拘繫之」，上窮也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',16)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
